class Solution { public:
    int idealArrays(int n, int maxValue) {
        const long long MOD=1000000007;
        int maxE=0; for(int x=maxValue;x>1;x/=2) ++maxE;
        vector<long long> fact(n+maxE+1,1), inv(fact.size(),1);
        for(int i=1;i<(int)fact.size();++i) fact[i]=fact[i-1]*i%MOD;
        auto power=[&](long long a,long long b){long long r=1;while(b){if(b&1)r=r*a%MOD;a=a*a%MOD;b>>=1;}return r;};
        inv.back()=power(fact.back(),MOD-2);
        for(int i=(int)inv.size()-1;i>0;--i) inv[i-1]=inv[i]*i%MOD;
        auto choose=[&](int a,int b){return fact[a]*inv[b]%MOD*inv[a-b]%MOD;};
        vector<int> spf(maxValue+1);
        for(int i=2;i<=maxValue;++i) if(!spf[i]) for(int j=i;j<=maxValue;j+=i) if(!spf[j]) spf[j]=i;
        long long ans=0;
        for(int v=1;v<=maxValue;++v){
            int x=v; long long ways=1;
            while(x>1){int p=spf[x],e=0;while(x%p==0){x/=p;++e;}ways=ways*choose(n+e-1,e)%MOD;}
            ans=(ans+ways)%MOD;
        }
        return (int)ans;
    }
};
